async def main():
    r = AsyncWebRouter("nimble", provider_config={"nimble": {"max_retries": 0}})
    dom = sys.argv[1]
    urls=set()
    for q in [dom, dom+" chief executive", "Quillmate CEO", dom+" leadership team"]:
